<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext,HttpException};
final class SiteDeliveryPlanService
{
 use DeliveryOperations;
 public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly SiteAccessService $access) {}
 private function kind(string $kind):void {if(!in_array($kind,['POST_ORDERS','CONTINUITY','RISK'],true))throw HttpException::notFound();}
 private function assigned(mixed $site):void {$employee=$this->employee();if(!$this->db->fetch('SELECT grant_id FROM user_site_grants WHERE company_id=:company AND user_id=:actor AND site_id=:site',['company'=>$this->company(),'actor'=>$this->actor(),'site'=>$site])&&!$this->db->fetch("SELECT shift_assignment_id FROM shift_assignments WHERE company_id=:company AND employee_id=:employee AND site_id=:site AND deleted_at IS NULL AND assignment_status IN ('ASSIGNED','CONFIRMED','IN_PROGRESS') AND shift_end_at>=:now",['company'=>$this->company(),'employee'=>$employee,'site'=>$site,'now'=>gmdate('Y-m-d H:i:s')]))throw HttpException::notFound();}
 private function plan(string $id):array {$r=$this->row('site_delivery_plans','plan_id',$id);$this->access->requireSite($r['site_id']);return $r;}
 public function list(string $kind,array $in,string $audience='STAFF'):array {$this->kind($kind);$this->fields($in,['site_id']);$s=$this->access->requireSite($in['site_id']??null);if($audience==='SELF')$this->assigned($s['site_id']);if($audience==='CLIENT')$this->mapped($s['client_id']);$p=['company'=>$this->company(),'site'=>$s['site_id'],'kind'=>$kind];$rows=$this->db->fetchAll('SELECT * FROM site_delivery_plans WHERE company_id=:company AND site_id=:site AND plan_kind=:kind'.($audience==='STAFF'?'':' AND effective_on<=:today AND client_id=:client').' ORDER BY revision DESC LIMIT 100',$audience==='STAFF'?$p:$p+['today'=>gmdate('Y-m-d'),'client'=>$s['client_id']]);foreach($rows as&$r){$r['content']=json_decode($r['content_json'],true,512,JSON_THROW_ON_ERROR);unset($r['content_json']);$r['acknowledgements']=$this->db->fetchAll('SELECT user_id,audience,acknowledged_at FROM site_delivery_acknowledgements WHERE company_id=:company AND plan_id=:id'.($audience==='STAFF'?'':' AND user_id=:actor'),$audience==='STAFF'?['company'=>$this->company(),'id'=>$r['plan_id']]:['company'=>$this->company(),'id'=>$r['plan_id'],'actor'=>$this->actor()]);$r['activations']=$kind==='CONTINUITY'&&$audience==='STAFF'?$this->db->fetchAll('SELECT * FROM continuity_activations WHERE company_id=:company AND plan_id=:id ORDER BY activation_id DESC',['company'=>$this->company(),'id'=>$r['plan_id']]):[];}return $rows;}
 public function publish(string $kind,array $in):array {return $this->atomic(function()use($kind,$in){$this->kind($kind);$this->fields($in,['site_id','expected_revision','title','effective_on','review_on','duties','contacts','scenarios','hazards']);$s=$this->access->requireSite($in['site_id']??null);$effective=$this->day($in['effective_on']??null);$review=$this->day($in['review_on']??null);if($effective<gmdate('Y-m-d')||$review<=$effective)throw HttpException::unprocessable('Choose a current/future effective date and later review date.');$last=$this->db->fetch('SELECT revision,effective_on FROM site_delivery_plans WHERE company_id=:company AND site_id=:site AND plan_kind=:kind ORDER BY revision DESC LIMIT 1',['company'=>$this->company(),'site'=>$s['site_id'],'kind'=>$kind]);if($this->number($in['expected_revision']??null,0)!==(int)($last['revision']??0)||($last&&$effective<$last['effective_on']))throw HttpException::conflict('Edition changed or effective date precedes the latest edition.');$content=[];
 if($kind==='POST_ORDERS'){$content=['duties'=>$this->strings($in['duties']??null),'contacts'=>$this->text($in['contacts']??null,4000)];}
 elseif($kind==='CONTINUITY'){$scenarios=$in['scenarios']??null;if(!is_array($scenarios)||!array_is_list($scenarios)||count($scenarios)<1||count($scenarios)>10)throw HttpException::unprocessable('Provide 1–10 continuity scenarios.');$out=[];foreach($scenarios as$c){if(!is_array($c))throw HttpException::unprocessable('Invalid scenario.');$this->fields($c,['type','steps','fallback_contact']);if(!in_array($c['type']??null,['POWER','NETWORK','STAFFING','OTHER'],true))throw HttpException::unprocessable('Unsupported outage type.');$out[]=['type'=>$c['type'],'steps'=>$this->strings($c['steps']??null),'fallback_contact'=>$this->text($c['fallback_contact']??null,1000)];}$content=['scenarios'=>$out];}
 else{$hazards=$in['hazards']??null;if(!is_array($hazards)||!array_is_list($hazards)||count($hazards)<1||count($hazards)>30)throw HttpException::unprocessable('Provide 1–30 hazards.');$out=[];foreach($hazards as$h){if(!is_array($h))throw HttpException::unprocessable('Invalid hazard.');$this->fields($h,['hazard','likelihood','impact','controls','owner_user_id']);$u=$this->operator($h['owner_user_id']??null,$s['site_id'],'risk_assessments.view');$l=$this->number($h['likelihood']??null,1,5);$i=$this->number($h['impact']??null,1,5);$out[]=['hazard'=>$this->text($h['hazard']??null,1000),'likelihood'=>$l,'impact'=>$i,'score'=>$l*$i,'rating'=>$l*$i>=15?'HIGH':($l*$i>=8?'MEDIUM':'LOW'),'controls'=>$this->strings($h['controls']??null,10),'owner_user_id'=>$u['user_id']];}$content=['hazards'=>$out];}
 $title=$this->text($in['title']??null,150);$json=json_encode($content,JSON_THROW_ON_ERROR);$hash=hash('sha256',json_encode([$s['site_id'],$s['client_id'],$kind,$title,$effective,$review,$content],JSON_THROW_ON_ERROR));$this->db->execute('INSERT INTO site_delivery_plans(company_id,site_id,client_id,plan_kind,revision,title,content_json,content_hash,effective_on,review_on,published_by_user_id,published_at) VALUES(:company,:site,:client,:kind,:revision,:title,:content,:hash,:effective,:review,:actor,:now)',['company'=>$this->company(),'site'=>$s['site_id'],'client'=>$s['client_id'],'kind'=>$kind,'revision'=>(int)($last['revision']??0)+1,'title'=>$title,'content'=>$json,'hash'=>$hash,'effective'=>$effective,'review'=>$review,'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);return $this->created('site_delivery_plan')+['content_hash'=>$hash];});}
 public function acknowledge(string $id,array $in,string $audience):array {return $this->atomic(function()use($id,$in,$audience){$this->fields($in,['expected_hash']);$r=$this->plan($id);$s=$this->access->requireSite($r['site_id']);if($audience==='CLIENT'){$this->mapped($s['client_id']);if($r['plan_kind']!=='RISK'||(string)$r['client_id']!==(string)$s['client_id'])throw HttpException::notFound();}else $this->assigned($r['site_id']);$latest=$this->db->fetch('SELECT plan_id FROM site_delivery_plans WHERE company_id=:company AND site_id=:site AND plan_kind=:kind AND effective_on<=:today ORDER BY revision DESC LIMIT 1',['company'=>$this->company(),'site'=>$r['site_id'],'kind'=>$r['plan_kind'],'today'=>gmdate('Y-m-d')]);if(!$latest||(string)$latest['plan_id']!==$id||!is_string($in['expected_hash']??null)||!hash_equals($r['content_hash'],$in['expected_hash']))throw HttpException::conflict('Read the latest effective edition.');$p=['company'=>$this->company(),'plan'=>$id,'actor'=>$this->actor(),'audience'=>$audience];if(!$this->db->fetch('SELECT acknowledgement_id FROM site_delivery_acknowledgements WHERE company_id=:company AND plan_id=:plan AND user_id=:actor AND audience=:audience',$p))$this->db->execute('INSERT INTO site_delivery_acknowledgements(company_id,plan_id,user_id,audience,content_hash,acknowledged_at) VALUES(:company,:plan,:actor,:audience,:hash,:now)',$p+['hash'=>$r['content_hash'],'now'=>gmdate('Y-m-d H:i:s')]);$this->history('site_plan',$id,'ACKNOWLEDGED',$audience);return ['acknowledged'=>true];});}
 public function activate(string $id,array $in):array {return $this->atomic(function()use($id,$in){$this->fields($in,['scenario_index','reason']);$r=$this->plan($id);if($r['plan_kind']!=='CONTINUITY'||$r['effective_on']>gmdate('Y-m-d'))throw HttpException::conflict('Choose an effective continuity plan.');$latest=$this->db->fetch("SELECT plan_id FROM site_delivery_plans WHERE company_id=:company AND site_id=:site AND plan_kind='CONTINUITY' AND effective_on<=:today ORDER BY revision DESC LIMIT 1",['company'=>$this->company(),'site'=>$r['site_id'],'today'=>gmdate('Y-m-d')]);if((string)$latest['plan_id']!==$id)throw HttpException::conflict('Use the current continuity edition.');$scenarios=json_decode($r['content_json'],true)['scenarios'];$index=$this->number($in['scenario_index']??null,0,count($scenarios)-1);$steps=array_map(fn($s)=>['step'=>$s,'completed_at'=>null,'actor_user_id'=>null],$scenarios[$index]['steps']);$this->db->execute('INSERT INTO continuity_activations(company_id,plan_id,scenario_index,reason,steps_json,started_by_user_id,started_at) VALUES(:company,:plan,:scenario,:reason,:steps,:actor,:now)',['company'=>$this->company(),'plan'=>$id,'scenario'=>$index,'reason'=>$this->text($in['reason']??null,2000),'steps'=>json_encode($steps,JSON_THROW_ON_ERROR),'actor'=>$this->actor(),'now'=>gmdate('Y-m-d H:i:s')]);return $this->created('continuity_activation');});}
 public function activationAction(string $id,string $action,array $in):array {return $this->atomic(function()use($id,$action,$in){$this->fields($in,['expected_revision','step_number','notes']);$r=$this->row('continuity_activations','activation_id',$id);$this->plan((string)$r['plan_id']);$this->revision($r,$in);if($r['state']!=='ACTIVE')throw HttpException::conflict('Activation ended.');$notes=$this->text($in['notes']??null,2000);$steps=json_decode($r['steps_json'],true);$state='ACTIVE';if($action==='step'){$i=$this->number($in['step_number']??null,1,count($steps))-1;if($steps[$i]['completed_at'])throw HttpException::conflict('Step already recorded.');$steps[$i]['completed_at']=gmdate('Y-m-d H:i:s');$steps[$i]['actor_user_id']=$this->actor();$steps[$i]['notes']=$notes;}elseif($action==='close'){if(array_filter($steps,fn($s)=>!$s['completed_at']))throw HttpException::conflict('Record all steps before closing.');$state='CLOSED';}elseif($action==='cancel')$state='CANCELLED';else throw HttpException::notFound();$this->db->execute('UPDATE continuity_activations SET state=:state,steps_json=:steps,revision=revision+1,closed_at=:closed,debrief=:notes WHERE company_id=:company AND activation_id=:id',['state'=>$state,'steps'=>json_encode($steps,JSON_THROW_ON_ERROR),'closed'=>$state==='ACTIVE'?null:gmdate('Y-m-d H:i:s'),'notes'=>$notes,'company'=>$this->company(),'id'=>$id]);$this->history('continuity',$id,strtoupper($action),$notes);return ['state'=>$state];});}
}
